add_action( 'wp', function () {
	if ( is_admin() || wp_doing_ajax() || is_feed() || is_embed() ) return;
	if ( defined( 'REST_REQUEST' ) && REST_REQUEST ) return;
	if ( ! ( is_front_page() || is_page( 35 ) ) ) return;
	if ( isset( $_GET['rw_tw_cdn'] ) ) return;

	ob_start( function ( $html ) {
		if ( ! is_string( $html ) || false === strpos( $html, 'cdn.tailwindcss.com' ) ) return $html;
		$n    = 0;
		$html = preg_replace( '#<script src="https://cdn\.tailwindcss\.com[^"]*"></script>\s*#', '', $html, 1, $n );
		if ( ! $n ) return $html;
		$html = preg_replace( '#<script>\s*tailwind\.config\s*=.*?</script>\s*#s', '', $html, 1 );
		$pos  = stripos( $html, '</head>' );
		if ( false === $pos ) return $html;
		return substr_replace( $html, '<style id="rw-tw-home">' . rw_tw_home_css() . '</style>', $pos, 0 );
	} );
}, -2 );